        {
                if (msg.sender != e4_partner) {
                        StatEvent("forbidden");
                        return; // thank you
                }
                uint nfvalue = msg.value; // preserve value in case changed in dev grant

                updateIcoStatus();

                holdoverBalance += nfvalue;
                partnerCredits += nfvalue;
                StatEventI("Payment", nfvalue);

                if (holdoverBalance > payoutThreshold
                        || payoutBalance > 0)
                        doPayout();


        }

