        assert((z = x - y) <= x);
    }

function mul(uint256 x, uint256 y) constant internal returns (uint256 z) {
        z = x * y;
        assert(x == 0 || z / x == y);
    }

function div(uint256 x, uint256 y) constant internal returns (uint256 z) {
        z = x / y;
    }

