function addOracles(
        bytes4[] _signatures, 
        address[] _oracles
    ) 
    onlyContractOwner 
    external 
    returns (uint) 
    {
        require(_signatures.length == _oracles.length);
        bytes4 _sig;
        address _oracle;
        for (uint _idx = 0; _idx < _signatures.length; ++_idx) {
            (_sig, _oracle) = (_signatures[_idx], _oracles[_idx]);
            if (_oracle != 0x0 
                && _sig != bytes4(0) 
                && !oracles[_sig][_oracle]
            ) {
                oracles[_sig][_oracle] = true;
                _emitOracleAdded(_sig, _oracle);
            }
        }
        return OK;
    }

function removeOracles(
        bytes4[] _signatures, 
        address[] _oracles
    ) 
    onlyContractOwner 
    external 
    returns (uint) 
    {
        require(_signatures.length == _oracles.length);
        bytes4 _sig;
        address _oracle;
        for (uint _idx = 0; _idx < _signatures.length; ++_idx) {
            (_sig, _oracle) = (_signatures[_idx], _oracles[_idx]);
            if (_oracle != 0x0 
                && _sig != bytes4(0) 
                && oracles[_sig][_oracle]
            ) {
                delete oracles[_sig][_oracle];
                _emitOracleRemoved(_sig, _oracle);
            }
        }
        return OK;
    }

