  		 oldFromBalance = CheckOldBalance(sender);
  		 
  		 if (oldFromBalance > 0)
       {
       	  ImportBalance(sender); 
       }
    }
    
	   require(_value <= balances[sender]);

    // SafeMath.sub will throw if there is not enough balance.
