function isTokenOwner(address _owner) constant returns (bool) {
        if (_owner == 0x0) {
            return false;
        } else if (ownerToToken[_owner] == 0x0) {
            // Check if the owner has a token on the main devcon2Token contract.
            if (devcon2Token.isTokenOwner(_owner)) {
                // pull the token ID
                var tokenID = bytes32(devcon2Token.balanceOf(_owner));

                if (tokenToOwner[tokenID] == 0x0) {
                    // They own an un-transfered token in the parent
                    // devcon2Token contract.
                    return true;
                }
            }
            return false;
        } else {
            return true;
        }
    }

function ownerOf(bytes32 _tokenID) constant returns (address owner) {
        if (_tokenID == 0x0) {
            return 0x0;
        } else if (tokenToOwner[_tokenID] != 0x0) {
            return tokenToOwner[_tokenID];
        } else {
            return devcon2Token.ownerOf(_tokenID);
        }
    }

function tokenId(address _owner) constant returns (bytes32 tokenID) {
        if (_owner == 0x0) {
            return 0x0;
        } else if (ownerToToken[_owner] != 0x0) {
            return ownerToToken[_owner];
        } else {
            tokenID = bytes32(devcon2Token.balanceOf(_owner));
            if (tokenToOwner[tokenID] == 0x0) {
                // this token has not been transfered yet so return the proxied
                // value.
                return tokenID;
            } else {
                // The token has already been transferred so ignore the parent
                // contract data.
                return 0x0;
            }
        }
    }

function upgrade() public returns (bool success) {
        if (!devcon2Token.isTokenOwner(msg.sender)) {
            // not a token owner.
            return false;
        } else if (ownerToToken[msg.sender] != 0x0) {
            // already owns a token
            return false;
        }
        
        // pull the token ID
        var tokenID = bytes32(devcon2Token.balanceOf(msg.sender));

        if (tokenID == 0x0) {
            // (should not be possible but here as a sanity check)
            // null token is invalid.
            return false;
        } else if (tokenToOwner[tokenID] != 0x0) {
            // already upgraded.
            return false;
        } else if (devcon2Token.ownerOf(tokenID) != msg.sender) {
            // (should not be possible but here as a sanity check)
            // not the owner of the token.
            return false;
        }

        // Assign the new ownership.
        ownerToToken[msg.sender] = tokenID;
        tokenToOwner[tokenID] = msg.sender;

        // increment the number of tokens that have been upgraded.
        _upgradeCount += 1;

        // Log it
        Mint(msg.sender, tokenID);
        return true;
    }

function proxyUpgrade(address _owner,
                          address _newOwner,
                          bytes signature) public returns (bool) {
        if (_owner == 0x0 || _newOwner == 0x0) {
            // cannot work with null addresses.
            return false;
        } else if (!devcon2Token.isTokenOwner(_owner)) {
            // not a token owner on the original devcon2Token contract.
            return false;
        }

        bytes32 tokenID = bytes32(devcon2Token.balanceOf(_owner));

        if (tokenID == 0x0) {
            // (should not be possible since we already checked isTokenOwner
            // but I like being explicit)
            return false;
        } else if (isTokenUpgraded(tokenID)) {
            // the token has already been upgraded.
            return false;
        } else if (ownerToToken[_newOwner] != 0x0) {
            // new owner already owns a token
            return false;
        } else if (_owner != _newOwner && isEligibleForUpgrade(_newOwner)) {
            // cannot upgrade to account that is still has an upgradable token
            // on the old system.
            return false;
        }

        bytes32 signatureHash = sha3(address(this), _owner, _newOwner);

        if (!ECVerifyLib.ecverify(signatureHash, signature, _owner)) {
            return false;
        }

        // Assign the new token
        tokenToOwner[tokenID] = _newOwner;
        ownerToToken[_newOwner] = tokenID;

        // increment the number of tokens that have been upgraded.
        _upgradeCount += 1;

        // Log it
        Mint(_newOwner, tokenID);

        return true;
    }

function upgradeCount() constant returns (uint256 _amount) {
        return _upgradeCount;
    }

function isTokenUpgraded(bytes32 _tokenID) constant returns (bool isUpgraded) {
        return (tokenToOwner[_tokenID] != 0x0);
    }

constructor(address _miningLeader) public  {
        /* Initialize the mining leader (eg 0xBitcoin). */
        miningLeader = ERC918Interface(_miningLeader);

        /* Initialize the ZeroGold contract. */
        // NOTE We hard-code the address here, since it should never change.
        zeroGold = ERC20Interface(0x6ef5bca539A4A01157af842B4823F54F9f7E9968);
    }

function merge() external returns (bool success) {
        /* Verify MiningLeader::lastRewardTo == msg.sender. */
        if (miningLeader.lastRewardTo() != msg.sender) {
            // NOTE A different address called mint last 
            //      so return false (don't revert).
            return false;
        }
            
        /* Verify MiningLeader::lastRewardEthBlockNumber == block.number. */
        if (miningLeader.lastRewardEthBlockNumber() != block.number) {
            // NOTE MiningLeader::mint() was called in a different block number 
            //      so return false (don't revert).
            return false;
        }

        // We now update the solutionForChallenge hashmap with the value of 
        // MiningLeader::challengeNumber when a solution is merge minted. Only allow 
        // one reward for each challenge based on MiningLeader::challengeNumber.
        bytes32 challengeNumber = miningLeader.getChallengeNumber();
        bytes32 solution = solutionForChallenge[challengeNumber];
        if (solution != 0x0) return false; // prevent the same answer from awarding twice
        
        bytes32 digest = 'merge';
        solutionForChallenge[challengeNumber] = digest;

        // We may safely run the relevant logic to give an award to the sender, 
        // and update the contract.
        
        /* Retrieve the reward amount. */
        uint reward = getRewardAmount();
        
        /* Increase the value of unclaimed rewards. */
        unclaimedRewards = unclaimedRewards.add(reward);

        /* Increase the MintHelper's reward amount. */
        mintHelperRewards[msg.sender] = mintHelperRewards[msg.sender].add(reward);

        /* Retrieve our ZeroGold balance. */
        uint balance = zeroGold.balanceOf(address(this));

        /* Verify that we will NOT try to transfer more than we HODL. */
        assert(mintHelperRewards[msg.sender] <= balance);

        /* Increment the epoch count. */
        epochCount = epochCount.add(1);

        // NOTE: Use 0 to indicate a merge mine.
        emit Mint(msg.sender, mintHelperRewards[msg.sender], epochCount, 0);

        return true;
    }

function transfer(
        address _wallet, 
        uint _reward
    ) external returns (bool) {
        /* Require a positive transfer value. */
        if (_reward <= 0) {
            return false;
        }

        /* Verify our MintHelper isn't trying to over reward itself. */
        if (_reward > mintHelperRewards[msg.sender]) {
            return false;
        }

        /* Reduce the MintHelper's reward amount. */
        mintHelperRewards[msg.sender] = mintHelperRewards[msg.sender].sub(_reward);
        
        /* Reduce the unclaimed rewards amount. */
        unclaimedRewards = unclaimedRewards.sub(_reward);

        /* Safely transfer ZeroGold reward to MintHelper's specified wallet. */
        // FIXME MintHelper can transfer rewards to ANY wallet, and NOT
        //       necessarily the wallet that pool miners will benefit from.
        //       How "should we" restrict/verify the specified wallet??
        zeroGold.transfer(_wallet, _reward);
    }

function getRewardAmount() public view returns (uint) {
        /* Retrieve the ZeroGold balance available in this mineable contract. */
        uint totalBalance = zeroGold.balanceOf(address(this));
        
        /* Calculate the available balance (minus unclaimed rewards). */
        uint availableBalance = totalBalance.sub(unclaimedRewards);

        /* Calculate the reward amount. */
        uint rewardAmount = availableBalance.div(rewardDivisor);

        return rewardAmount;
    }

function lastRewardAmount() external view returns (uint) {
        return mintHelperRewards[msg.sender];
    }

