function withdrawCommission() public onlyOwner {
    require(commissionEarned > minimumBalance);
    uint _amount = commissionEarned - minimumBalance;
    commissionEarned -= _amount;
    totalWithdrawn += _amount;
    owner.transfer(_amount);
	}

