function doSendBounds(bytes32 queryId) public payable {
      uint sta = lableStatus[queryId];
      require(sta == 2);

      uint totalWin = 0;
      uint len = lableCount[queryId];

      address to = lableUser[queryId];
      for(uint aa = 0 ; aa<len; aa++){
        //中奖
        if(betList[queryId][aa][5] == 2){
          totalWin+=betList[queryId][aa][6];
        }
      }

      if(totalWin > 0){
          to.transfer(totalWin);//转账
      }
      lableStatus[queryId] = 3;
      contractBalance=this.balance;
      maxProfit=(this.balance * maxmoneypercent)/100;
    }

function checkWinMoney(uint[7] storage betinfo,uint[3] codes) internal {
      uint rates;
      if(betinfo[1] ==1){
          //大小 豹子不中奖
          if(codes[0] == codes[1] && codes[1] == codes[2]){
            betinfo[5]=1;//未中奖
          }else{
            uint sum = codes[0]+codes[1]+codes[2];
            if(sum >= 4 && sum < 11){
              sum = 4;//小
            }else if(sum >= 11 && sum < 18){
              sum = 17;//大
            }else{
              sum = 0;
            }
            betinfo[5]=1;
            if(sum >0 && betinfo[2] == sum){
                betinfo[5]=2;
                rates = getPlayRate(betinfo[1],0);
                betinfo[6]=betinfo[3]*rates/10;
            }

          }
      }else if(betinfo[1] == 2){
          //单双 豹子不中奖
          if(codes[0] == codes[1] && codes[1] == codes[2]){
            betinfo[5]=1;//未中奖
          }else{
            uint sums = codes[0]+codes[1]+codes[2];
            if(sums % 2 == 0){
              sums = 2;//双
            }else{
              sums = 3;//单
            }
            betinfo[5]=1;
            if(sums == betinfo[2]){
              betinfo[5]=2;
              rates = getPlayRate(betinfo[1],0);
              betinfo[6]=betinfo[3]*rates/10;
            }

          }

        }else if(betinfo[1] == 3){
          //二同号复选
          betinfo[5]=1;//不中奖
          if(codes[0] == codes[1] || codes[1] == codes[2] ){
            uint tmp = 0;
            if(codes[0] == codes[1] ){
              tmp = codes[0];
            }else if(codes[1] == codes[2]){
              tmp = codes[1];
            }
            if(tmp == betinfo[2]){
              betinfo[5]=2;
              rates = getPlayRate(betinfo[1],0);
              betinfo[6]=betinfo[3]*rates;
            }

          }
        }else if(betinfo[1] == 4){
          //三同号单选
          betinfo[5]=1;//不中奖
          if(codes[0] == codes[1] && codes[1] == codes[2] ){
            if(codes[0] == betinfo[2]){
              betinfo[5]=2;
              rates = getPlayRate(betinfo[1],0);
              betinfo[6]=betinfo[3]*rates;
            }
          }
        }else if(betinfo[1] == 5){
          //三同号通选
          betinfo[5]=1;//不中奖
          if(codes[0] == codes[1] && codes[1] == codes[2] ){
              betinfo[5]=2;
              rates = getPlayRate(betinfo[1],0);
              betinfo[6]=betinfo[3]*rates;
          }
        }else if(betinfo[1] == 6){
          //和值 豹子不中奖
          if(codes[0] == codes[1] && codes[1] == codes[2]){
            betinfo[5]=1;//不中奖
          }else{
            betinfo[5]=1;//不中奖
            uint sum6 = codes[0]+codes[1]+codes[2];
            if(sum6 == betinfo[2]){
              betinfo[5]=2;
              rates = getPlayRate(betinfo[1],sum6);
              betinfo[6]=betinfo[3]*rates;
            }
          }
        }else if(betinfo[1] == 7){
          //二不同号 豹子不中奖
          if(codes[0] == codes[1] && codes[1] == codes[2]){
            betinfo[5]=1;//不中奖
          }else{
            uint[2] memory haoma = getErbutongHao(betinfo[2]);
            bool atmp=false;
            bool btmp=false;
            for(uint ai=0;ai<codes.length;ai++){
              if(codes[ai] == haoma[0]){
                atmp = true;
                continue;
              }
              if(codes[ai] == haoma[1]){
                btmp = true;
                continue;
              }
            }
            betinfo[5]=1;
            if(atmp && btmp){
              betinfo[5]=2;
              rates = getPlayRate(betinfo[1],0);
              betinfo[6]=betinfo[3]*rates;
            }
          }
        }else if(betinfo[1] == 8){
          //猜1个号，赔率放大了10倍
          uint tmpp = 0;
          betinfo[5]=1;//不中奖
          if(codes[0] == betinfo[2]){
            tmpp++;
          }
          if(codes[1] == betinfo[2]){
            tmpp++;
          }
          if(codes[2] == betinfo[2]){
            tmpp++;
          }
          if(tmpp > 0){
            betinfo[5]=2;
            rates = getPlayRate(betinfo[1],tmpp);
            betinfo[6]=betinfo[3]*rates/10;
          }
        }

    }

function getErbutongHao(uint sss) internal view returns(uint[2]){
      uint[2] memory result ;
      if(sss == 12){
        result = [uint(1),2];
      }else if(sss == 13){
         result = [uint(1),3];
      }else if(sss == 14){
         result = [uint(1),4];
      }else if(sss == 15){
         result = [uint(1),5];
      }else if(sss == 16){
         result = [uint(1),6];
      }else if(sss == 23){
         result = [uint(2),3];
      }else if(sss == 24){
         result = [uint(2),4];
      }else if(sss == 25){
         result = [uint(2),5];
      }else if(sss == 26){
         result = [uint(2),6];
      }else if(sss == 34){
         result = [uint(3),4];
      }else if(sss == 35){
         result = [uint(3),5];
      }else if(sss == 36){
         result = [uint(3),6];
      }else if(sss == 45){
         result = [uint(4),5];
      }else if(sss == 46){
         result = [uint(4),6];
      }else if(sss == 56){
         result = [uint(5),6];
      }
      return (result);
    }

