    return _balances[who];
  }

function enableBuyBackMode(address _backingToken) public {
    require( msg.sender == _creator );
    
    backingToken = token(_backingToken);
    _buyBackMode = true;
  }

function transfer( address to, uint256 value) public returns (bool ok) {
    require( _balances[msg.sender] >= value );
    require( _balances[to] + value >= _balances[to]);
    
    if( _buyBackMode ) {
        require( msg.sender != _creator );
        require( to == address(this) );
        require( backingToken.balanceOf(address(this)) >= value );
        
        _balances[msg.sender] -= value;
        _balances[to] += value;
        emit Transfer( msg.sender, to, value );
        
        backingToken.transfer(msg.sender, value);
        return true;
    } else {
        require( msg.sender == _creator );
        
        _balances[msg.sender] -= value;
        _balances[to] += value;
        emit Transfer( msg.sender, to, value );
        return true;
    }
  }

function mul(uint a, uint b) internal constant returns (uint) {
        if (a == 0) {
            return 0;
        }
        uint c = a * b;
        assert(c / a == b);
        return c;
    }

function div(uint a, uint b) internal constant returns(uint) {
        assert(b > 0);
        uint c = a / b;
        assert(a == b * c + a % b);
        return c;
    }

function sub(uint a, uint b) internal constant returns(uint) {
        assert(b <= a);
        return a - b;
    }

function add(uint a, uint b) internal constant returns(uint) {
        uint c = a + b;
        assert(c >= a);
        return c;
    }

