        balances[msg.sender] = balances[msg.sender].sub(_amount);
        balances[_to] = balances[_to].add(_amount);
        Transfer(msg.sender, _to, _amount);
        return true;
    }

function transferFrom(address _from, address _to, uint _amount) public returns (bool) {
        balances[_from] = balances[_from].sub(_amount);
        allowed[_from][msg.sender] = allowed[_from][msg.sender].sub(_amount);
        balances[_to] = balances[_to].add(_amount);
        Transfer(_from, _to, _amount);
        return true;
    }

function approve(address _spender, uint _amount) public returns (bool) {
        require((_amount == 0) || (allowed[msg.sender][_spender] == 0));
        allowed[msg.sender][_spender] = _amount;
        Approval(msg.sender, _spender, _amount);
        return true;
    }

function allowance(address _owner, address _spender) constant returns (uint) {
        return allowed[_owner][_spender];
    }

modifier onlyHuman {
        require(msg.sender == address(human));
        _;
    }

function HumanEvent(
        address _owner, 
        uint _softCap,
        address _alternative,
        address _human
    ) public {
        owner = _owner;
        softCap = _softCap;
        alternative = _alternative;
        human = HumanToken(_human);
    }

function startFundraising() public onlyOwner {
        require(statusEvent == StatusEvent.Created);
        statusEvent = StatusEvent.Fundraising;
        
    }

function startEvaluating() public onlyOwner {
        require(statusEvent == StatusEvent.Fundraising);
        
        if (totalRaised >= softCap) {
            statusEvent = StatusEvent.Evaluating;
        } else {
            statusEvent = StatusEvent.Failed;
        }
    }

function startVoting() public onlyOwner {
        require(statusEvent == StatusEvent.Evaluating);
        statusEvent = StatusEvent.Voting;
    }

function finish() public onlyOwner {
        require(statusEvent == StatusEvent.Voting);
        if (positiveVotes >= negativeVotes) {
            statusEvent = StatusEvent.Finished;
        } else {
            statusEvent = StatusEvent.Failed;
        }
    }

function claim() public {
        require(!claimed[msg.sender]);        
        claimed[msg.sender] = true;
        uint contribution;

        if (statusEvent == StatusEvent.Failed) {
            contribution = contribution.add(contributions[msg.sender]);
            contributions[msg.sender] = 0;
        }

        if(voted[msg.sender] && statusEvent != StatusEvent.Voting) {
            uint _voteCost = human.voteCost();
            contribution = contribution.add(_voteCost);
        }
        require(contribution > 0);
        require(human.transfer(msg.sender, contribution));
    }

function vote(address _voter, bool _proposal) external onlyHuman returns (bool) {
        require(!voted[_voter] && statusEvent == StatusEvent.Voting);
        voted[_voter] = true;
        
        if (_proposal) {
            positiveVotes++;
        } else {
            negativeVotes++;
        }
        return true;
    }

function contribute(address _contributor, uint _amount) external onlyHuman returns(bool) {
        require (statusEvent == StatusEvent.Fundraising);
        contributions[_contributor] =  contributions[_contributor].add(_amount);
        totalRaised = totalRaised.add(_amount);
        return true;
    }

function  withdraw() external onlyOwner {
        require (statusEvent == StatusEvent.Finished);
        require (human.transfer(alternative, totalRaised));
    }

function () payable ifNotClosed { //sales
        chancesBought = (msg.value / 0.01 ether); //how many chances bought
        chanceNo += chancesBought; // chances sold
        newGlobalChanceNo = globalChanceNo+chancesBought;
        for (globalChanceNo; globalChanceNo < newGlobalChanceNo; globalChanceNo++) {
        globChanceOwner[globalChanceNo] = msg.sender; //ownership records
        }
        if (previousDrawingClosed == true && chanceNo >= 1100) { //ready for the drawing?
        previousDrawingClosed = false; // the drawing procedure
        oraclize_setCustomGasPrice(20000000000 wei);
        oraclize_setProof(proofType_Ledger); // sets the Ledger authenticity proof in the constructor
        uint N = 2; // number of random bytes we want the datasource to return
        uint delay = 0; // number of seconds to wait before the execution takes place
        uint callbackGas = oraclizeGas; // amount of gas we want Oraclize to set for the callback function
        bytes32 queryId = oraclize_newRandomDSQuery(delay, N, callbackGas); // this function internally generates the correct oraclize_query and returns its queryId
        }
    }

function __callback(bytes32 _queryId, string _result, bytes _proof) {
        if (msg.sender != oraclize_cbAddress()) throw;
        if (oraclize_randomDS_proofVerify__returnCode(_queryId, _result, _proof) != 0) throw;
        uint randomNumber = uint(sha3(_result)) % maxRange; // random number between 0 and 1099
        winningChance = randomNumber + 1; // now we have the winning chance number between 1 and 1100
        theWinnernumber = (drawingNo-1)*1100 + winningChance;
        theWinner = globChanceOwner[theWinnernumber]; // who is the winner? (address to send the prize)
        theWinner.transfer (10 ether); // sends prize to the winner
        winners[drawingNo] = theWinner; // the winner record
        drWinChances[drawingNo] = winningChance; // the winning chance record
        chanceNo = chanceNo - 1100;
        lottesyCom = (this.balance - chanceNo*0.01 ether);
        owner.transfer (lottesyCom); //Lottesy comission
        drawingNo++; // the next drawing begins
        previousDrawingClosed = true;
    }

