      changeRound(1547596800, 666666667 ether, 32481, _newAmount);
    } else if (round == 2) {
      changeRound(1543622400, 333333333 ether, 38977, _newAmount);
    } else if (round == 1) {
      changeRound(1539648000, 250000000 ether, 48721, _newAmount);
    }
  }

