function _transfer(address _from, address _to, uint256 _tokenId) internal {
        // Since the number of kittens is capped to 2^32 we can't overflow this
        ownershipTokenCount[_to]++;
        // transfer ownership
        petIndexToOwner[_tokenId] = _to;
        // When creating new kittens _from is 0x0, but we can't account that address.
        if (_from != address(0)) {
            ownershipTokenCount[_from]--;
            // clear any previously approved ownership exchange
            delete petIndexToApproved[_tokenId];
        }
        // Emit the transfer event.
        emit Transfer(_from, _to, _tokenId);
    }

function _createPet(
        uint256 _generation,
        uint256 _genes,
        address _owner,
        uint256 _grade,
        uint256 _level,
        uint256 _params,
        uint256 _skills
    )
        internal
        returns (uint)
    {
        // These requires are not strictly necessary, our calling code should make
        // sure that these conditions are never broken. However! _createKitty() is already
        // an expensive call (for storage), and it doesn't hurt to be especially careful
        // to ensure our data structures are always valid.
        require(_generation == uint256(uint16(_generation)));

        // New pet starts with the same cooldown as parent gen/2
        uint16 cooldownIndex = uint16(_generation / 2);
        if (cooldownIndex > 13) {
            cooldownIndex = 13;
        }

        Pet memory _pet = Pet({
            genes: _genes,
            birthTime: uint64(now),            
            generation: uint16(_generation),
            grade: uint16(_grade), 
            level: uint16(_level), 
            params: uint16(_params),            
            skills: uint16(_skills)
        });
        uint256 newPetId = pets.push(_pet) - 1;

        // It's probably never going to happen, 4 billion cats is A LOT, but
        // let's just be 100% sure we never let this happen.
        require(newPetId == uint256(uint32(newPetId)));

        // emit the birth event
        emit Birth(
            _owner,
            newPetId,
            _pet.genes
        );

        // This will assign ownership, and also emit the Transfer event as
        // per ERC721 draft
        _transfer(0, _owner, newPetId);

        return newPetId;
    }

