            _endBlock,
            _rate,
            _minDeposit,
            _maxWhitelistLength,
            _whitelistThreshold,
            _token,
            _tokenMaximumSupply,
            _wallet
        );

        // Transfer NokuCustomCrowdsale ownership to the client
        customCrowdsale.transferOwnership(msg.sender);

        require(pricingPlan.payFee(SERVICE_NAME, CREATE_AMOUNT, msg.sender), "fee payment failed");
