        return (b >= 0 && a - b <= a) || (b < 0 && a - b > a);
    }

function safeToMul(int a, int b) internal pure returns (bool) {
        return (b == 0) || (a * b / b == a);
    }

function add(int a, int b) internal pure returns (int) {
