function() public payable {
    // If we get paid in ETH, convert to WETH so payouts work the same.
    // Converting to WETH also makes payouts a bit safer, as we don't have to
    // worry about code execution if the stakeholder is a contract.
    if(!_upgrading) {
      weth.deposit.value(msg.value)();
    }
  }

function transferToken(address token, address recipient, uint quantity) external onlyOwner {
    require(ERC20(token).transfer(recipient, quantity));
  }

function upgradeWeth(address _newWeth) external onlyOwner {
    // At some point in the future we may want to upgrade from one WETH
    // contract to a new one.
    _upgrading = true;
    weth.withdraw(weth.balanceOf(address(this)));
    _upgrading = false;
    weth = WETH9(_newWeth);
    weth.deposit.value(address(this).balance)();
  }

function redeem(uint shares, address[] tokens) public {
    require(
      stakeToken.balanceOf(msg.sender) >= shares &&
      stakeToken.allowance(msg.sender, address(this)) >= shares,
      "Insufficient balance or allowance"
    );
    uint totalShares = stakeToken.totalSupply();
    // Burn the sender's share before sending their tokens to ensure that a
    // malicious token contract couldn't use reentrancy to empty the pot.
    stakeToken.burnFrom(msg.sender, shares);

    for(uint i=0; i < tokens.length; i++) {
      uint balance = ERC20(tokens[i]).balanceOf(address(this));
      ERC20(tokens[i]).transfer(msg.sender, SafeMath.mul(balance, shares) / totalShares);
    }
  }

function unit()
        external
        pure
        returns (uint)
    {
        return UNIT;
    }

function preciseUnit()
        external
        pure 
        returns (uint)
    {
        return PRECISE_UNIT;
    }

function multiplyDecimal(uint x, uint y)
        internal
        pure
        returns (uint)
    {
        /* Divide by UNIT to remove the extra factor introduced by the product. */
        return x.mul(y) / UNIT;
    }

function _multiplyDecimalRound(uint x, uint y, uint precisionUnit)
        private
        pure
        returns (uint)
    {
        /* Divide by UNIT to remove the extra factor introduced by the product. */
        uint quotientTimesTen = x.mul(y) / (precisionUnit / 10);

        if (quotientTimesTen % 10 >= 5) {
            quotientTimesTen += 10;
        }

        return quotientTimesTen / 10;
    }

function multiplyDecimalRoundPrecise(uint x, uint y)
        internal
        pure
        returns (uint)
    {
        return _multiplyDecimalRound(x, y, PRECISE_UNIT);
    }

function multiplyDecimalRound(uint x, uint y)
        internal
        pure
        returns (uint)
    {
        return _multiplyDecimalRound(x, y, UNIT);
    }

function divideDecimal(uint x, uint y)
        internal
        pure
        returns (uint)
    {
        /* Reintroduce the UNIT factor that will be divided out by y. */
        return x.mul(UNIT).div(y);
    }

function _divideDecimalRound(uint x, uint y, uint precisionUnit)
        private
        pure
        returns (uint)
    {
        uint resultTimesTen = x.mul(precisionUnit * 10).div(y);

        if (resultTimesTen % 10 >= 5) {
            resultTimesTen += 10;
        }

        return resultTimesTen / 10;
    }

function divideDecimalRound(uint x, uint y)
        internal
        pure
        returns (uint)
    {
        return _divideDecimalRound(x, y, UNIT);
    }

function divideDecimalRoundPrecise(uint x, uint y)
        internal
        pure
        returns (uint)
    {
        return _divideDecimalRound(x, y, PRECISE_UNIT);
    }

function decimalToPreciseDecimal(uint i)
        internal
        pure
        returns (uint)
    {
        return i.mul(UNIT_TO_HIGH_PRECISION_CONVERSION_FACTOR);
    }

function preciseDecimalToDecimal(uint i)
        internal
        pure
        returns (uint)
    {
        uint quotientTimesTen = i / (UNIT_TO_HIGH_PRECISION_CONVERSION_FACTOR / 10);

        if (quotientTimesTen % 10 >= 5) {
            quotientTimesTen += 10;
        }

        return quotientTimesTen / 10;
    }

