function buyImplementation(address buyerAddress, uint64 buyerId, uint maxAmount, uint8 v, bytes32 r, bytes32 s)
        private returns (bool)
    {
        // check the signature
        bytes32 hash = sha256("Eidoo icoengine authorization", this, buyerAddress, buyerId, maxAmount);
        address signer = ecrecover(hash, v, r, s);
        if (!isKycSigner[signer]) {
            revert();
        } else {
            uint256 totalPayed = alreadyPayed[buyerId].add(msg.value);
            require(totalPayed <= maxAmount);
            alreadyPayed[buyerId] = totalPayed;
            KycVerified(signer, buyerAddress, buyerId, maxAmount);
            return releaseTokensTo(buyerAddress);
        }
    }

function BitLumensCrowdsale(
      address [] kycSigner,
      address _token,
      address _wallet,
      uint _startTime,
      uint _roundTwoTime,
      uint _roundThreeTime,
      uint _roundFourTime,
      uint _roundFiveTime,
      uint _endTime,
      uint _BlsPreIco,
      uint _blsTotalCap,
      uint _softCapUsd,
      uint _hardCapUsd,
      uint _ethUsdExchangeCents
      )
        public payable
        KYCBase(kycSigner)
    {
        require(_token != address(0));
        require(_wallet != address(0));

        require(bitlumensAccount != address(0));
        require(teamAccount != address(0));
        require(bountyAccount != address(0));
        //please make sure that the start in 3)depoly_tokenSale is larger than now before migrate
        require(_startTime > now);
        require (_startTime < _roundTwoTime);
        require (_roundTwoTime < _roundThreeTime);
        require (_roundThreeTime < _roundFourTime);
        require (_roundFourTime < _roundFiveTime);
        require (_roundFiveTime < _endTime);


      // OAR = OraclizeAddrResolverI(0xDD6CdC488799a0C6ABF7339f7FBFbb9B8C7C84f6);


        token = BLS(_token);
        wallet = _wallet;

