function bytesToUint2(bytes b) returns (uint) {
    uint result = 0;
    for (uint i=1; i < b.length; i++) {
      uint x = uint(uint(b[i]));
      if (x > 0)
        x = x - 48;
      result = result + x*(10**(b.length-i-1));
    }
    return result;
  }

