        withdraw.state = WithdrawState.Withdrawn;

        // transfer fund to clients account
        ERC20(_tokenAddress).transfer(clientAddress, amount);

        // log withdrawn
        emit PaymentWithdrawn(_orderId, clientAddress, amount);
    }

