        bonusPeriod25 = startPublicSale.add(12 days);
        bonusPeriod50 = startPublicSale.add(9 days);
        bonusPeriod100 = startPublicSale.add(6 days);
        bonusPeriod150 = startPublicSale.add(3 days);
